import{z as s,x as B,o as t,c as d,q as r,j as n,D as e,d as l,s as o,S as i,b as E}from"./chunks/framework.C8m1ZpeB.js";const c=JSON.parse('{"title":"VQ-VAE","description":"","frontmatter":{"title":"VQ-VAE","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/vq-vae.md","filePath":"llm/vq-vae.md","lastUpdated":1791413859000}'),p={name:"llm/vq-vae.md"};function m(D,a,_,V,h,k){const A=B("Mermaid");return t(),d("div",null,[a[2]||(a[2]=r('<h1 id="vq-vae" tabindex="-1">VQ-VAE <a class="header-anchor" href="#vq-vae" aria-label="Permalink to &quot;VQ-VAE&quot;">​</a></h1><div class="epigraph"><p>把连续隐变量换成码本里最近的向量，编码器输出就变成可当 token 的下标。生成模型于是可以在离散序列上做似然。</p><footer>—— van den Oord, Vinyals, Kavukcuoglu, VQ-VAE</footer></div><p><a href="/llm/expert-granularity-law">上一课</a>以专家粒度给「架构进阶」收尾：同样的激活预算下，FFN 专家切到通信-计算比与路由抖动允许的最细处为止。架构问完，本课程问像素如何进（生成式）模型。主干 <a href="/llm/vit-as-encoder">ViT</a> 给出连续 patch；生成还常要离散码，才能接自回归 LM。本课写 VQ-VAE。缺口是向量量化这一层，不是再讲卷积。后课 VQGAN 默认码本已经能重构，但不够锐。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>像素上直接 softmax 不可行：\\(H\\times W\\times 3\\) 的连续空间没有可枚举的类别。连续 VAE 的 \\(z\\) 好解码、不好当词表——对 \\(z\\) 做 CE 仍要先离散化，绕回原问题。van den Oord 等人把编码器输出 \\(z_e(x)\\) 量化到码本 \\(\\{e_k\\}\\) 中最近项 \\(z_q\\)，解码器只看 \\(z_q\\)，下标 \\(k\\) 就是视觉 token。训练要同时学编码器、码本、解码器，并防止码本崩溃（只用少数项）。三项损失各管一个对象：</p> \\[\\mathcal L=\\|x-D(z_q)\\|^2+\\|\\mathrm{sg}(z_e)-z_q\\|^2+\\beta\\,\\|z_e-\\mathrm{sg}(z_q)\\|^2 \\]<p>stop-grad 两侧各放一次、方向不同，这不是随手写的。码本项把梯度挡在 \\(z_e\\) 外、只动码字：码字是聚心，应当追随编码器输出的分布，分配由最近邻裁决；若两侧梯度都通，编码器与码字互相追着跑，最近邻分配不停翻转，训练震荡。承诺项把梯度挡在 \\(z_q\\) 外、只动编码器，\\(\\beta\\)（原论文取 \\(0.25\\)）压低它的权重：编码器不必为迁就离散格点牺牲重构，但要被拉住不每步换胞腔——没有它，同一区域前后两步映到不同下标，下游 LM 看到的标签序列不稳定，等于在噪声标签上做语言建模。</p><p>与检索嵌入不同：这里的离散化是为了生成与似然，不是为了余弦近邻。</p><p><span class="marginnote">直觉类比：最近邻量化就像只用一盒 16 色蜡笔临摹照片——每种真实颜色都被强制换成蜡笔盒里最接近的那支（码字），记录的不再是颜色本身而是「用了第几支蜡笔」（下标）。蜡笔越多临摹越像，但每支被用到的次数也越少；如果一半蜡笔从没被碰过，盒子的有效色数就在悄悄缩水。</span></p><p><span class="marginnote">直通估计器让 \\(z_q\\) 的梯度抄到 \\(z_e\\)。码本用指数滑动平均或损失项更新。崩溃时重构还行、词表有效大小接近 1，后接 LM 会学到无信息序列。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>最近邻 argmin 没有梯度，量化层对编码器不可导，码本与编码器的联动有两条路线。路线一是损失项加直通：上面的码本项把码字拉向分配到它的 \\(z_e\\)，直通估计器把解码器损失对 \\(z_q\\) 的梯度原样抄给 \\(z_e\\)，把量化当恒等——有偏但简单，小码本下够用。路线二是指数滑动平均：不给码本写损失，按批内分配把每个码字向「分配到它的 \\(z_e\\) 的均值」做 EMA，附 Laplace 平滑防止久未选中的码字漂死；码本更新不受编码器梯度尺度影响，大码本上更稳，代价是多一组与编码器学习率耦合的动量与平滑超参，配不平仍会崩。</p><p>验收写成两道闸门而不是一个分：重构 FID/PSNR 判码里留了多少信息，码本使用率（熵、死码比例）判离散化有没有退化。崩溃是正反馈：少数码字被选中就更靠近数据、更易再被选中，死码拿不到梯度，有效词表缩到接近 \\(1\\)；先修量化（重置死码到批内编码器输出）再训上游 LM，否则 LM 在无信息序列上白训。下采样倍数决定 token 数：压得越狠，空间细节越少、序列越短。</p><p><span class="marginnote">数字实例：\\(256 \\times 256\\) 的图按 8 倍下采样得到 \\(32 \\times 32 = 1024\\) 个位置，配 \\(8192\\) 大小的码本，就是一篇「1024 个词、词表 8k」的视觉文档——长度是同样分辨率文本 token 的几十倍。压到 16 倍则只剩 256 个 token，序列短了，但每个 token 要负责 \\(16 \\times 16\\) 像素的细节，预测更难、重构更糊。</span></p>',14)),(t(),n(i,null,{default:e(()=>[o(A,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20X%5B%22%E5%9B%BE%E5%83%8F%22%5D%20--%3E%20ENC%5B%22%E7%BC%96%E7%A0%81%E5%99%A8%20z_e%22%5D%0A%20%20ENC%20--%3E%20Q%5B%22%E6%9C%80%E8%BF%91%E7%A0%81%E5%AD%97%20z_q%22%5D%0A%20%20Q%20--%3E%20DEC%5B%22%E8%A7%A3%E7%A0%81%E9%87%8D%E6%9E%84%22%5D%0A%20%20Q%20--%3E%20ID%5B%22%E7%A6%BB%E6%95%A3%E4%B8%8B%E6%A0%87%20token%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[l(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("h2",{id:"机制",tabindex:"-1"},[l("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=E("p",null,"量化把连续空间按最近邻划成 Voronoi 胞腔，胞腔中心是码字。生成时 LM 只建模胞腔下标的联合分布，胞腔内的细节交给解码器凭码字与上下文补——「语义在码、纹理在解码器」的分工从这里开始。码本大小的两难由此可算：码本太小，胞腔过大，脸与文字糊；太大则每个下标的样本被摊薄、预测更难，还添死码风险，序列长度却分文不减。下采样倍数是另一根轴：同样码本大小，压得狠则每个 token 摊的像素多、单 token 更难预测。这是后课连续对离散的主轴。",-1)),a[5]||(a[5]=E("p",null,"码本崩溃不是外因事故，而是量化规则自带的正反馈：被选中的码字随数据移动、更容易再被选中，没被选中的码字拿不到梯度、原地漂死，形成一条自我强化的回路；常用的急救手段是在每个 batch 后把死码重置到该批的编码器输出上。",-1)),(t(),n(i,null,{default:e(()=>[o(A,{id:"mermaid-48",class:"mermaid",graph:"flowchart%20TD%0A%20%20BIAS%5B%22%E5%88%9D%E5%A7%8B%E5%8C%96%E5%81%8F%E6%96%9C%E6%88%96%E7%A8%80%E7%96%8F%E6%89%B9%22%5D%20--%3E%20FEW%5B%22%E5%B0%91%E6%95%B0%E7%A0%81%E5%AD%97%E8%A2%AB%E9%A2%91%E7%B9%81%E9%80%89%E4%B8%AD%22%5D%0A%20%20FEW%20--%3E%20MOVE%5B%22%E8%BF%99%E4%BA%9B%E7%A0%81%E5%AD%97%E9%9A%8F%E6%95%B0%E6%8D%AE%E7%A7%BB%E5%8A%A8%22%5D%0A%20%20MOVE%20--%3E%20CLOSER%5B%22%E5%AF%B9%E6%96%B0%E6%A0%B7%E6%9C%AC%E6%9B%B4%E8%BF%91%22%5D%0A%20%20CLOSER%20--%3E%20FEW%0A%20%20FEW%20--%3E%20DEAD%5B%22%E5%85%B6%E4%BD%99%E7%A0%81%E5%AD%97%E9%9B%B6%E5%88%86%E9%85%8D%22%5D%0A%20%20DEAD%20--%3E%20NOGRAD%5B%22%E6%8B%BF%E4%B8%8D%E5%88%B0%E6%A2%AF%E5%BA%A6%22%5D%0A%20%20NOGRAD%20--%3E%20DEAD%0A%20%20DEAD%20--%3E%20RESET%5B%22%E9%87%8D%E7%BD%AE%E5%88%B0%E6%89%B9%E5%86%85%E7%BC%96%E7%A0%81%E5%99%A8%E8%BE%93%E5%87%BA%22%5D%0A%20%20RESET%20--%3E%20FEW2%5B%22%E5%9B%9E%E5%88%B0%E5%81%A5%E5%BA%B7%E7%AB%9E%E4%BA%89%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[l(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=r('<p><span class="marginnote">常见误区：初学者容易以为「码本开大点总没错」。实际上码本从 8k 涨到 64k，token 序列长度一个不少，每个下标的训练样本却被摊薄 8 倍，LM 更难预测，死码比例还可能飙升——有效词表可能远小于名义大小。判断标准是使用率熵，不是 \\(K\\) 的数值。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>VQ-VAE 重构偏糊，因为损失是像素级、没有感知对抗：\\(\\ell_2\\) 在多个统计相似的纹理解上取平均，高频被抹平。下一课 VQGAN 用 GAN 与感知损失改解码器，码本才够当高质量图像 tokenizer。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>VQ-VAE 用最近码字把图像变成离散下标，供似然模型使用。</li><li>码本损失与承诺损失各挡一侧梯度，分别只动码字与编码器。</li><li>码本更新走 STE 损失或 EMA 两条路线；必须盯使用率，防止崩溃。</li><li>像素损失导致模糊，交给 VQGAN。</li><li>出处：van den Oord 等 VQ-VAE。</li></ul>',5))])}const q=s(p,[["render",m]]);export{c as __pageData,q as default};
